package com.masaakis.security;
import jakarta.servlet.*;import jakarta.servlet.http.*;import org.springframework.stereotype.Component;import org.springframework.web.filter.OncePerRequestFilter;import java.io.IOException;import java.time.Instant;import java.util.Set;import java.util.concurrent.*;
@Component public class ApiRateLimitFilter extends OncePerRequestFilter{private record Bucket(long window,long count){}private final ConcurrentHashMap<String,Bucket>buckets=new ConcurrentHashMap<>();
 @Override protected boolean shouldNotFilter(HttpServletRequest r){return!r.getRequestURI().startsWith("/api/");}
 @Override protected void doFilterInternal(HttpServletRequest r,HttpServletResponse response,FilterChain chain)throws ServletException,IOException{Limit l=limit(r);long now=Instant.now().getEpochSecond(),window=now/l.seconds;String key=r.getRemoteAddr()+"|"+r.getMethod()+"|"+group(r.getRequestURI());Bucket b=buckets.compute(key,(k,v)->v==null||v.window!=window?new Bucket(window,1):new Bucket(window,v.count+1));if(buckets.size()>50_000)buckets.entrySet().removeIf(e->e.getValue().window<window-2);if(b.count>l.requests){response.setStatus(429);response.setContentType("application/json");response.setHeader("Retry-After",String.valueOf(l.seconds-now%l.seconds));response.getWriter().write("{\"status\":429,\"code\":\"RATE_LIMITED\",\"message\":\"Çok fazla istek; kısa süre sonra yeniden deneyin.\"}");return;}chain.doFilter(r,response);}
 private Limit limit(HttpServletRequest r){String u=r.getRequestURI();if(u.contains("/auth/register"))return new Limit(5,3600);if(u.contains("/auth/login"))return new Limit(30,300);if(u.contains("/public/table/exchange"))return new Limit(30,60);if(u.contains("/webhooks/"))return new Limit(120,60);if(!Set.of("GET","HEAD","OPTIONS").contains(r.getMethod()))return new Limit(120,60);return new Limit(600,60);}private String group(String u){if(u.startsWith("/api/public/table/exchange/"))return"/api/public/table/exchange";return u.replaceAll("/[0-9a-fA-F-]{32,36}","/{id}");}private record Limit(long requests,long seconds){}
}
